BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY;
SELECT json_build_object('transaction_read_only',current_setting('transaction_read_only'),'isolation',current_setting('transaction_isolation'),'as_of',transaction_timestamp());
WITH universe AS (SELECT code FROM data_center_asset_master WHERE asset_type='stock' AND exchange IN ('SSE','SZSE','BSE') AND (is_active=true OR is_active IS NULL)), pubs AS (SELECT * FROM data_center_canonical_publication WHERE dataset_key='equity.quote.snapshot' AND publication_key='current' AND state='published' AND must_not_use_for_decision=false AND (superseded_at IS NULL OR reinstated_at IS NOT NULL)), facts AS (SELECT count(*) AS rows,count(DISTINCT asset_code) AS covered_assets,min(snapshot_at) AS oldest,max(snapshot_at) AS newest,count(*) FILTER(WHERE raw_payload_hash='') AS missing_raw_hash FROM data_center_quote_snapshot WHERE asset_code IN (SELECT code FROM universe)), sources AS (SELECT source,count(*) AS rows,count(DISTINCT asset_code) AS assets,min(snapshot_at) AS oldest,max(snapshot_at) AS newest FROM data_center_quote_snapshot WHERE asset_code IN (SELECT code FROM universe) GROUP BY source), members AS (SELECT m.*,f.id AS resolved_fact_id,f.asset_code AS resolved_asset_code,f.source AS fact_source,f.raw_payload_hash AS fact_raw_payload_hash,f.quality_status AS fact_quality_status,f.revision_number AS fact_revision_number,f.snapshot_at AS fact_date,(f.asset_code IN (SELECT code FROM universe)) AS belongs_to_universe FROM data_center_publication_member m JOIN pubs p ON p.publication_id=m.publication_id LEFT JOIN data_center_quote_snapshot f ON m.fact_pk=f.id::text) SELECT json_build_object('dataset','equity.quote.snapshot','universe_count',(SELECT count(*) FROM universe),'facts',(SELECT row_to_json(facts) FROM facts),'sources',(SELECT json_agg(sources) FROM sources),'publications',(SELECT json_agg(pubs) FROM pubs),'members',(SELECT json_agg(members ORDER BY natural_key,source) FROM members));
WITH universe AS (SELECT code FROM data_center_asset_master WHERE asset_type='stock' AND exchange IN ('SSE','SZSE','BSE') AND (is_active=true OR is_active IS NULL)), pubs AS (SELECT * FROM data_center_canonical_publication WHERE dataset_key='equity.price.bar' AND publication_key='current' AND state='published' AND must_not_use_for_decision=false AND (superseded_at IS NULL OR reinstated_at IS NOT NULL)), facts AS (SELECT count(*) AS rows,count(DISTINCT asset_code) AS covered_assets,min(bar_date) AS oldest,max(bar_date) AS newest,count(*) FILTER(WHERE raw_payload_hash='') AS missing_raw_hash FROM data_center_price_bar WHERE asset_code IN (SELECT code FROM universe)), sources AS (SELECT source,count(*) AS rows,count(DISTINCT asset_code) AS assets,min(bar_date) AS oldest,max(bar_date) AS newest FROM data_center_price_bar WHERE asset_code IN (SELECT code FROM universe) GROUP BY source), members AS (SELECT m.*,f.id AS resolved_fact_id,f.asset_code AS resolved_asset_code,f.source AS fact_source,f.raw_payload_hash AS fact_raw_payload_hash,f.quality_status AS fact_quality_status,f.revision_number AS fact_revision_number,f.bar_date AS fact_date,(f.asset_code IN (SELECT code FROM universe)) AS belongs_to_universe FROM data_center_publication_member m JOIN pubs p ON p.publication_id=m.publication_id LEFT JOIN data_center_price_bar f ON m.fact_pk=f.id::text) SELECT json_build_object('dataset','equity.price.bar','universe_count',(SELECT count(*) FROM universe),'facts',(SELECT row_to_json(facts) FROM facts),'sources',(SELECT json_agg(sources) FROM sources),'publications',(SELECT json_agg(pubs) FROM pubs),'members',(SELECT json_agg(members ORDER BY natural_key,source) FROM members));
WITH universe AS (SELECT code FROM data_center_asset_master WHERE asset_type='stock' AND exchange IN ('SSE','SZSE','BSE') AND (is_active=true OR is_active IS NULL)), pubs AS (SELECT * FROM data_center_canonical_publication WHERE dataset_key='equity.valuation.fact' AND publication_key='current' AND state='published' AND must_not_use_for_decision=false AND (superseded_at IS NULL OR reinstated_at IS NOT NULL)), facts AS (SELECT count(*) AS rows,count(DISTINCT asset_code) AS covered_assets,min(val_date) AS oldest,max(val_date) AS newest,count(*) FILTER(WHERE raw_payload_hash='') AS missing_raw_hash,count(*) FILTER (WHERE available_at IS NULL) AS missing_available_at FROM data_center_valuation_fact WHERE asset_code IN (SELECT code FROM universe)), sources AS (SELECT source,count(*) AS rows,count(DISTINCT asset_code) AS assets,min(val_date) AS oldest,max(val_date) AS newest FROM data_center_valuation_fact WHERE asset_code IN (SELECT code FROM universe) GROUP BY source), members AS (SELECT m.*,f.id AS resolved_fact_id,f.asset_code AS resolved_asset_code,f.source AS fact_source,f.raw_payload_hash AS fact_raw_payload_hash,f.quality_status AS fact_quality_status,f.revision_number AS fact_revision_number,f.val_date AS fact_date,(f.asset_code IN (SELECT code FROM universe)) AS belongs_to_universe FROM data_center_publication_member m JOIN pubs p ON p.publication_id=m.publication_id LEFT JOIN data_center_valuation_fact f ON m.fact_pk=f.id::text) SELECT json_build_object('dataset','equity.valuation.fact','universe_count',(SELECT count(*) FROM universe),'facts',(SELECT row_to_json(facts) FROM facts),'sources',(SELECT json_agg(sources) FROM sources),'publications',(SELECT json_agg(pubs) FROM pubs),'members',(SELECT json_agg(members ORDER BY natural_key,source) FROM members));
WITH universe AS (SELECT code FROM data_center_asset_master WHERE asset_type='stock' AND exchange IN ('SSE','SZSE','BSE') AND (is_active=true OR is_active IS NULL)), pubs AS (SELECT * FROM data_center_canonical_publication WHERE dataset_key='equity.financial.fact' AND publication_key='current' AND state='published' AND must_not_use_for_decision=false AND (superseded_at IS NULL OR reinstated_at IS NOT NULL)), facts AS (SELECT count(*) AS rows,count(DISTINCT asset_code) AS covered_assets,min(period_end) AS oldest,max(period_end) AS newest,count(*) FILTER(WHERE raw_payload_hash='') AS missing_raw_hash,count(*) FILTER (WHERE available_at IS NULL) AS missing_available_at FROM data_center_financial_fact WHERE asset_code IN (SELECT code FROM universe)), sources AS (SELECT source,count(*) AS rows,count(DISTINCT asset_code) AS assets,min(period_end) AS oldest,max(period_end) AS newest FROM data_center_financial_fact WHERE asset_code IN (SELECT code FROM universe) GROUP BY source), members AS (SELECT m.*,f.id AS resolved_fact_id,f.asset_code AS resolved_asset_code,f.source AS fact_source,f.raw_payload_hash AS fact_raw_payload_hash,f.quality_status AS fact_quality_status,f.revision_number AS fact_revision_number,f.period_end AS fact_date,(f.asset_code IN (SELECT code FROM universe)) AS belongs_to_universe FROM data_center_publication_member m JOIN pubs p ON p.publication_id=m.publication_id LEFT JOIN data_center_financial_fact f ON m.fact_pk=f.id::text) SELECT json_build_object('dataset','equity.financial.fact','universe_count',(SELECT count(*) FROM universe),'facts',(SELECT row_to_json(facts) FROM facts),'sources',(SELECT json_agg(sources) FROM sources),'publications',(SELECT json_agg(pubs) FROM pubs),'members',(SELECT json_agg(members ORDER BY natural_key,source) FROM members));
COMMIT;
